void HAL_UART_IRQHandler(UART_HandleTypeDef *huart)
{
  /* Simplified UART interrupt handler for emulation */
  /* In emulation, we simulate interrupt handling without hardware dependencies */

  /* Safety check */
  if (huart == NULL)
  {
    return;
  }

  /* In emulation, we simulate the most common interrupt scenarios:
   * 1. Receiver data ready (RXNE)
   * 2. Transmitter empty (TXE) 
   * 3. Transmission complete (TC)
   * 4. Error conditions
   */

  /* Simulate reading interrupt status flags */
  /* In real hardware, these would be read from USART->SR register */
  uint32_t simulated_isrflags = 0;

  /* Determine which interrupts to simulate based on UART state */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* Simulate receiver data ready interrupt */
    simulated_isrflags |= 0x20; /* RXNE flag */
  }

  if (huart->gState == HAL_UART_STATE_BUSY_TX)
  {
    /* Simulate transmitter empty interrupt */
    simulated_isrflags |= 0x80; /* TXE flag */

    /* Also simulate transmission complete if all data sent */
    if (huart->TxXferCount == 0)
    {
      simulated_isrflags |= 0x40; /* TC flag */
    }
  }

  /* Handle receiver interrupt if simulated */
  if ((simulated_isrflags & 0x20) != 0) /* RXNE */
  {
    /* Call UART_Receive_IT if it exists */
    /* In emulation, we'll handle data reception elsewhere */
    /* Just update state and call callback if reception complete */
    if (huart->RxXferCount > 0)
    {
      /* Simulate receiving one byte */
      if (huart->RxXferCount > 0)
      {
        huart->RxXferCount--;
      }

      /* Check if reception is complete */
      if (huart->RxXferCount == 0)
      {
        huart->RxState = HAL_UART_STATE_READY;

        /* Call receive complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
        if (huart->RxCpltCallback != NULL)
        {
          huart->RxCpltCallback(huart);
        }
#else
        HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
      }
    }
    return;
  }

  /* Handle transmitter empty interrupt if simulated */
  if ((simulated_isrflags & 0x80) != 0) /* TXE */
  {
    /* In emulation, we simulate transmission by decrementing counter */
    if (huart->TxXferCount > 0)
    {
      huart->TxXferCount--;
    }

    /* If all data sent, simulate transmission complete */
    if (huart->TxXferCount == 0)
    {
      huart->gState = HAL_UART_STATE_READY;

      /* Call transmit complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
      if (huart->TxCpltCallback != NULL)
      {
        huart->TxCpltCallback(huart);
      }
#else
      HAL_UART_TxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
    }
    return;
  }

  /* Handle transmission complete interrupt if simulated */
  if ((simulated_isrflags & 0x40) != 0) /* TC */
  {
    /* Transmission already handled by TXE, just return */
    return;
  }

  /* Handle error conditions if any */
  if (huart->ErrorCode != HAL_UART_ERROR_NONE)
  {
    /* Call error callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    if (huart->ErrorCallback != NULL)
    {
      huart->ErrorCallback(huart);
    }
#else
    HAL_UART_ErrorCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */

    /* Clear error code after handling */
    huart->ErrorCode = HAL_UART_ERROR_NONE;
    return;
  }

  /* If we get here, no interrupt to handle in this simulation */
  /* This is normal - real hardware would have many interrupt sources */
  /* but in emulation we only simulate the most common ones */
}
